const isCampaignMode = typeof globalThis.CAMPAIGN_MODE === 'undefined' ? false : globalThis.CAMPAIGN_MODE;

export function indirimliFiyat(fiyat, yuzde) {
  const indirimOrani = isCampaignMode ? yuzde / 2 : yuzde;
  const indirimliFiyat = fiyat - (fiyat * (indirimOrani / 100));

  return Math.round(indirimliFiyat);
}"}

